// @vitest-environment jsdom

/**
 * `GeneratedFiles`: the download cards under a message for the files that
 * `code_interpreter` produced (xlsx, docx, pdf, pptx, ...).
 *
 * The gateway hands generated bytes to the browser as `data:` URIs (the
 * `attachment` SSE frame), and a browser blocks top-level navigation to a `data:`
 * URL, so the card is an `<a download>`: that is the one control that works for
 * this kind of link. This file pins what the card carries (the data URI as its
 * href, the file name as its download name, a Norwegian type label and a size) so
 * that the live proof of the Office outputs (H5) is checking a card that is known
 * to be wired right, and a failure there points at the model or the sandbox and
 * not at the markup. It also pins the split the message makes between a card and
 * an inline preview: a generated PNG is shown as an image, never as a file card.
 */

import { render } from '@solidjs/testing-library'
import { describe, expect, it } from 'vitest'
import { GeneratedFiles } from './ChatMessages'
import { deriveConversationNodes } from '@/shared/chat-nodes/derive'
import type { ChatTurn, GeneratedFile } from './chat-types'

const XLSX = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
const DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
const PPTX = 'application/vnd.openxmlformats-officedocument.presentationml.presentation'

/** A data URI whose decoded payload is exactly `bytes` long. */
function dataUri(mime: string, bytes: number): string {
  return `data:${mime};base64,${btoa('a'.repeat(bytes))}`
}

function file(overrides: Partial<GeneratedFile> & Pick<GeneratedFile, 'name' | 'mime'>): GeneratedFile {
  return { id: `call-1-file-${overrides.name}`, size: 0, url: dataUri(overrides.mime, 10), ...overrides }
}

const cards = (container: HTMLElement) => Array.from(container.querySelectorAll<HTMLElement>('.verevon-chat-generated-file'))
const downloadAnchor = (card: HTMLElement) => card.querySelector<HTMLAnchorElement>('a[download]')!

describe('GeneratedFiles', () => {
  it('offers every file as a download anchor: the data URI as href, the file name as download name', () => {
    const files = [
      file({ name: 'salg-q3.xlsx', mime: XLSX, size: 6144 }),
      file({ name: 'statusnotat.docx', mime: DOCX, size: 4096 }),
      file({ name: 'sammendrag.pdf', mime: 'application/pdf', size: 2048 }),
      file({ name: 'kvartalsrapport.pptx', mime: PPTX, size: 35_840 }),
    ]
    const { container } = render(() => <GeneratedFiles files={files} />)
    const rendered = cards(container)
    expect(rendered).toHaveLength(4)
    rendered.forEach((card, index) => {
      const anchor = downloadAnchor(card)
      expect(anchor.getAttribute('href')).toBe(files[index]!.url)
      expect(anchor.getAttribute('href')).toMatch(/^data:/)
      expect(anchor.getAttribute('download')).toBe(files[index]!.name)
      expect(anchor.getAttribute('aria-label')).toBe(`Last ned ${files[index]!.name}`)
      expect(anchor.textContent).toContain(files[index]!.name)
    })
  })

  it('labels each file in Norwegian by its type, and shows an unknown type as it is', () => {
    const { container } = render(() => (
      <GeneratedFiles
        files={[
          file({ name: 'a.xlsx', mime: XLSX }),
          file({ name: 'b.docx', mime: DOCX }),
          file({ name: 'c.pdf', mime: 'application/pdf' }),
          file({ name: 'd.pptx', mime: PPTX }),
          file({ name: 'e.bin', mime: 'application/octet-stream' }),
        ]}
      />
    ))
    const labels = cards(container).map((card) => card.querySelector('em')?.textContent)
    expect(labels).toEqual([
      'Excel-regneark (XLSX)',
      'Word-dokument (DOCX)',
      'PDF-dokument',
      'PowerPoint-presentasjon (PPTX)',
      // Not a wrong-but-confident label: an unrecognized type is shown as it is.
      'application/octet-stream',
    ])
  })

  it('shows the size the gateway reported, and measures the data URI when it reported none', () => {
    const { container } = render(() => (
      <GeneratedFiles
        files={[
          // Reported: used as is, even though the URI is smaller.
          file({ name: 'reported.xlsx', mime: XLSX, size: 2048, url: dataUri(XLSX, 10) }),
          // Not reported: decoded from the base64 payload.
          file({ name: 'measured.xlsx', mime: XLSX, size: 0, url: dataUri(XLSX, 3072) }),
          // Not reported and not measurable: no size is better than a wrong one.
          file({ name: 'unknown.xlsx', mime: XLSX, size: 0, url: 'data:' }),
        ]}
      />
    ))
    const sizes = cards(container).map((card) => downloadAnchor(card).querySelector('span')?.textContent ?? null)
    expect(sizes).toEqual(['2 KB', '3 KB', null])
  })

  it('offers open-in-a-tab only for a real http(s) URL, never for a data URI', () => {
    const { container } = render(() => (
      <GeneratedFiles
        files={[
          file({ name: 'local.pdf', mime: 'application/pdf' }),
          file({ name: 'remote.pdf', mime: 'application/pdf', url: 'https://files.example.test/remote.pdf' }),
        ]}
      />
    ))
    const [local, remote] = cards(container)
    expect(local!.querySelector('.verevon-chat-generated-file__open')).toBeNull()
    const open = remote!.querySelector<HTMLAnchorElement>('.verevon-chat-generated-file__open')
    expect(open?.getAttribute('href')).toBe('https://files.example.test/remote.pdf')
    expect(open?.getAttribute('target')).toBe('_blank')
    expect(open?.getAttribute('rel')).toBe('noopener noreferrer')
  })
})

describe('what a message does with the files code_interpreter produced', () => {
  const turn = (files: GeneratedFile[]): ChatTurn => ({
    id: 'a1',
    role: 'assistant',
    content: 'Filene er laget.',
    createdAt: '2026-10-01T10:00:00.000Z',
    streaming: false,
    tools: [],
    attachments: [],
    files,
  })

  it('shows a PNG chart as an inline preview and keeps the workbook as a download card', () => {
    const chart = file({ name: 'besokstall.png', mime: 'image/png', size: 20_480, url: dataUri('image/png', 20_480) })
    const workbook = file({ name: 'salg-q3.xlsx', mime: XLSX, size: 6144 })
    const nodes = deriveConversationNodes(turn([workbook, chart]))

    const previews = nodes.find((node) => node.kind === 'image-previews')
    expect(previews?.kind === 'image-previews' && previews.previews.map((preview) => preview.src)).toEqual([chart.url])
    const cardsNode = nodes.find((node) => node.kind === 'files')
    expect(cardsNode?.kind === 'files' && cardsNode.files.map((entry) => entry.name)).toEqual(['salg-q3.xlsx'])
  })

  it('shows no preview node when no file is an image', () => {
    const nodes = deriveConversationNodes(turn([file({ name: 'sammendrag.pdf', mime: 'application/pdf' })]))
    expect(nodes.some((node) => node.kind === 'image-previews')).toBe(false)
    expect(nodes.some((node) => node.kind === 'files')).toBe(true)
  })
})
